import {Renderer,Geometry,transform,project,V} from './engine.js';
import {makeScene,channelGeometry,channelPoint,drawPerson,C,PEOPLE} from './scene.js';
import {Rain,ARENAS,PLOTS,RESOURCES,LANDMARKS,MOVES,obstacles,segmentCircle} from './realm.js';
export class WorldView {
 constructor(canvas){this.r=new Renderer(canvas);this.base=makeScene(this.r);this.eye=[15,17,34];this.target=[0,1,8];this.yaw=0;this.pitch=.48;this.distance=12;this.atlas=false;this.channelKey='';this.channels=null;this.preview=null;this.reduced=false;const r=this.r;
 const arenas=new Geometry();for(const a of Object.values(ARENAS)){arenas.cone([a.x,-.05,a.z],[a.x,0,a.z],a.r,a.r,[.26,.32,.35],96);arenas.cone([a.x,-18,a.z],[a.x,-.06,a.z],a.r*.6,a.r,[.13,.22,.26],40);arenas.ring(a.x,.08,a.z,a.r-.4,.09,C.pale,80);for(let i=0;i<12;i++){const angle=i/12*Math.PI*2,x=a.x+Math.cos(angle)*(a.r-1),z=a.z+Math.sin(angle)*(a.r-1);arenas.cone([x,0,z],[x,3.7,z],.25,.12,C.pale);arenas.sphere(x,3.8,z,.22,.3,.22,C.gold,8,5);}}
 this.arenas=r.mesh(arenas);const crystal=new Geometry();crystal.cone([0,0,0],[0,2.2,0],.72,0,[.28,.48,.6],6);crystal.cone([0,0,0],[0,-.5,0],.72,0,[.22,.33,.45],6);this.crystal=r.mesh(crystal);
 const foe=new Geometry();foe.sphere(0,.9,0,.65,.7,.56,[.3,.29,.40],9,6);foe.cone([0,1.1,0],[0,2.1,0],.5,.04,[.58,.48,.65],6);foe.box(0,1.2,.55,.4,.09,.06,[1,.44,.25]);for(const side of[-1,1]){foe.cone([side*.5,.9,0],[side*1.1,.15,.5],.13,.06,[.4,.35,.43]);foe.cone([side*.35,.8,-.3],[side*.65,.04,-.6],.16,.06,[.3,.3,.37]);}this.foe=r.mesh(foe);
 const boss=new Geometry();boss.cone([0,.2,0],[0,4.5,0],1.8,1.1,[.29,.34,.35],10);boss.sphere(0,4.7,0,1.2,1.2,1.15,C.pale,10,8);boss.box(0,4.8,1,.8,.16,.2,C.gold);for(const side of[-1,1]){boss.cone([side*1,3.8,0],[side*3,1.3,.2],.48,.27,[.38,.40,.36]);boss.cone([side*3,1.3,.2],[side*3.2,.2,1],.27,.6,C.stone);boss.cone([side*.6,5.3,0],[side*2.3,7,-.5],.24,.04,C.gold);}boss.ring(0,3.8,0,1.55,.08,C.gold);this.boss=r.mesh(boss);
 const house=new Geometry();house.cone([0,0,0],[0,2.7,0],2.1,2,C.pale,8);house.cone([0,2.7,0],[0,4,0],2.7,.1,[.24,.43,.43],8);house.box(0,1.1,1.9,1.1,2.2,.2,C.dark);house.box(1.1,1.7,1.65,.45,.6,.15,C.gold);this.house=r.mesh(house);
 const farm=new Geometry();farm.box(0,.16,0,3.7,.3,3.7,[.28,.26,.2]);for(let i=-1;i<2;i++)for(let j=-1;j<2;j++){farm.cone([i,.3,j],[i,.9,j],.045,.02,C.teal);farm.sphere(i,.95,j,.32,.12,.3,C.teal,6,4);}this.farm=r.mesh(farm);
 const cover=new Geometry().box(0,1.1,0,3.5,2.2,3.5,C.stone);cover.cone([0,2.2,0],[0,2.8,0],2.6,.2,C.pale,4);this.cover=r.mesh(cover);
 const sword=new Geometry().cone([0,0,0],[0,0,2],.09,.015,C.light,5);sword.box(0,0,.1,.65,.08,.1,C.gold);this.sword=r.mesh(sword);
 const disc=new Geometry().cone([0,0,0],[0,.012,0],1,1,[1,1,1],48);this.disc=r.mesh(disc);const ring=new Geometry().ring(0,0,0,1,.025,[1,1,1],48);this.ring=r.mesh(ring);
 const flag=new Geometry().cone([0,0,0],[0,3.3,0],.045,.045,C.pale);flag.quad([0,3.2,0],[1.3,2.9,0],[1.15,2.2,0],[0,2.4,0],[1,1,1]);this.flag=r.mesh(flag);
 const gate=new Geometry();for(const side of[-1,1]){gate.cone([side*1.6,0,0],[side*1.3,3.5,0],.18,.14,C.pale);gate.cone([side*1.3,3.5,0],[0,4.7,0],.14,.04,C.pale);}gate.ring(0,2.5,0,1,.025,C.gold);this.gate=r.mesh(gate);
 }
 rebuild(s){const key=JSON.stringify(s.rain.channels);if(key!==this.channelKey){this.channelKey=key;if(this.channels)this.r.dispose(this.channels);this.channels=this.r.mesh(channelGeometry(s.rain.channels));}}
 setPreview(plan){if(this.preview)this.r.dispose(this.preview);this.preview=plan?this.r.mesh(channelGeometry(Object.fromEntries(plan.map(([from,to,capacity])=>[from+'>'+to,{from,to,capacity}])) ,true)):null;}
 drawActor(s,a,t,human=false){const r=this.r,m=this.base,y=(a.y||0)+(s.mode==='world'&&Rain.onBridge(a.x,a.z)&&Rain.bridgeOpen(s.rain)?.16:0),act=a.action,move=act&&MOVES[act.kind];if(a.hp<=0||a.dead)return;
 if(human||a.team==='amber'||a.team==='teal'){let tint=human?(s.hero.discipline==='stone'?[1.05,.95,.82]:s.hero.discipline==='gale'?[.82,1.04,1.2]:[1,1,1]):a.team==='amber'?[1.3,1.1,.65]:[.8,1.1,1.35];drawPerson(r,m,a.x,y,a.z,a.angle,t,(a.walk||0),tint);if(human||s.mode!=='world'){const phase=move?act.frame/(move.startup+move.active+move.recovery):0,sw=move?Math.sin(phase*Math.PI)*1.4:0;const reach=move&&act.frame>=move.startup&&act.frame<move.startup+move.active?1.45:1;r.draw(this.sword,transform(a.x+Math.cos(a.angle)*.42,y+1.1,a.z-Math.sin(a.angle)*.42,1,1,reach,a.angle+sw-.5),{glow:move?.12:0});}if(a.guard)r.draw(this.ring,transform(a.x+Math.sin(a.angle)*.7,y+.11,a.z+Math.cos(a.angle)*.7,1.1,1,1.1),{tint:C.gold,glow:.9});}else if(a.boss){r.draw(this.boss,transform(a.x,0,a.z,1,1+Math.sin(t*1.8)*.012,1,a.angle));}else{r.draw(this.foe,transform(a.x,.03+Math.abs(Math.sin(t*6))*.05,a.z,1,1,1,a.angle));}
 r.draw(m.shadow,transform(a.x,.025,a.z,a.boss?2:.65,1,a.boss?2:.5),{alpha:.3});if(a.invuln>0||a.dodge>21&&a.dodge<=31)r.draw(this.ring,transform(a.x,.15,a.z,1,1,1),{tint:C.teal,glow:.9});}
 render(s,t,dt,paused=false){this.rebuild(s);const r=this.r,h=s.hero,at=this.reduced?0:t;let target=[h.x,1.4+h.y,h.z],eye;if(this.atlas){eye=[h.x+8,63,h.z+28];target=[h.x,0,h.z-6];}else{let len=this.distance;const ex=h.x+Math.sin(this.yaw)*len*Math.cos(this.pitch),ez=h.z+Math.cos(this.yaw)*len*Math.cos(this.pitch);for(const o of obstacles(s)){let hit=segmentCircle(h.x,h.z,ex,ez,o.x,o.z,o.r+.5);if(hit!==null)len=Math.max(2.5,Math.min(len,len*hit-.3));}eye=[h.x+Math.sin(this.yaw)*len*Math.cos(this.pitch),Math.max(3,2+Math.sin(this.pitch)*len+h.y),h.z+Math.cos(this.yaw)*len*Math.cos(this.pitch)];}const blend=1-Math.exp(-dt*9);this.eye=this.eye.map((v,i)=>v+(eye[i]-v)*blend);this.target=this.target.map((v,i)=>v+(target[i]-v)*blend);r.begin(this.eye,this.target,at,this.atlas);
 r.draw(this.base.distant,transform(0,Math.sin(at*.24)*.14,0));r.draw(this.base.earth);r.draw(this.base.architecture);r.draw(this.base.green,transform(),{sway:this.reduced?0:.006});r.draw(this.base.orchard,transform(),{tint:s.rain.storage.orchard>=5?[1,1.17,.95]:[.68,.71,.56],sway:this.reduced?0:.005});r.draw(this.base.reeds,transform(),{tint:s.rain.storage.habitat>=5?[1,1.15,1]:[.7,.68,.46],sway:this.reduced?0:.01});r.draw(Rain.bridgeOpen(s.rain)?this.base.bridge:this.base.closed);r.draw(this.arenas);
 for(const b of s.structures){const p=PLOTS[b.plot];if(b.type==='farm')r.draw(this.farm,transform(p.x,0,p.z));else if(b.type==='beacon'){r.draw(this.crystal,transform(p.x,.6,p.z,1.4,1.5,1.4),{glow:.25});r.draw(this.ring,transform(p.x,.1,p.z,2,1,2),{tint:C.gold,glow:.8});}else r.draw(this.house,transform(p.x,0,p.z),{tint:b.type==='workshop'?[1.1,1,.83]:b.type==='quarry'?[.88,.95,1]:[1,1,1]});}
 for(const p of PLOTS)if(!s.structures.some(b=>b.plot===p.id))r.draw(this.ring,transform(p.x,.06,p.z,2.2,1,2.2),{tint:[.5,.65,.55],alpha:.4});
 for(const n of RESOURCES){if(n.item==='ore')for(let i=0;i<3;i++)r.draw(this.crystal,transform(n.x+Math.sin(i*3)*.7,0,n.z+Math.cos(i*3)*.7,.5,.5+i*.1,.5),{glow:.1});if(n.item==='stone')r.draw(this.cover,transform(n.x,0,n.z,.5,.4,.5));}
 for(const n of LANDMARKS.filter(n=>['boss','ctf','duel'].includes(n.kind)))r.draw(this.gate,transform(n.x,0,n.z));
 for(const[id,n]of Object.entries(Rain.NODES)){const fill=id==='spring'?1.65:Rain.SINKS.includes(id)?.85*Math.sqrt(s.rain.storage[id]/10):.75;r.draw(this.base.water,transform(n.x,.44,n.z,fill,1,fill),{glow:.35,alpha:.85});r.draw(this.base.orb,transform(n.x,1.15+Math.sin(at+n.x)*.08,n.z,.65,.65,.65),{glow:.6});}if(this.channels)r.draw(this.channels,transform(),{glow:.18});if(this.preview)r.draw(this.preview,transform(),{glow:.7,alpha:.6});for(const c of Object.values(s.rain.channels)){const f=s.rain.flows[c.from+'>'+c.to]||0;for(let i=0;i<f;i++){let p=channelPoint(c.from,c.to,(at*.17+i/f)%1);r.draw(this.base.orb,transform(...p,.4,.4,.4),{glow:1});}}
 for(const p of PEOPLE){const x=p.id==='vey'?s.rain.cargo.x+2.4:p.x,z=p.id==='vey'?s.rain.cargo.z+.6:p.z;drawPerson(r,this.base,x,0,z,p.id==='vey'?Math.PI:.5,at,p.id==='vey'&&s.rain.cargo.status==='traveling'&&!paused?.5:0,p.color.map(v=>v/.7));}r.draw(this.base.cart,transform(s.rain.cargo.x,Rain.onBridge(0,s.rain.cargo.z)&&Rain.bridgeOpen(s.rain)?.16:0,s.rain.cargo.z));
 for(const w of s.workers){drawPerson(r,this.base,w.x,0,w.z,w.angle||0,at,w.phase==='traveling'||w.phase==='carrying'?.6:0,[.86,1,.85]);if(w.cargo)r.draw(this.cover,transform(w.x,1.3,w.z,.16,.16,.16),{tint:C.gold});}
 if(s.mode==='world')r.draw(this.base.pet,transform(s.pet.x,.03+Math.abs(Math.sin(at*6))*.055,s.pet.z,1,1,1,s.pet.angle),{glow:s.pet.bond*.025});
 if(s.mode!=='world')for(const o of obstacles(s))r.draw(this.cover,transform(o.x,0,o.z,o.r/2,1,o.r/2));
 this.drawActor(s,h,at,true);for(const a of s.enemies)this.drawActor(s,a,at);
 if(s.activity?.flags)for(const f of s.activity.flags)r.draw(this.flag,transform(f.x,f.carrier?1:0,f.z),{tint:f.team==='amber'?[1,.72,.28]:[.32,.75,1],glow:.3});
 if(s.mode==='boss'&&s.bossDefeated&&!s.cacheClaimed){r.draw(this.cover,transform(75,0,-47,.5,.4,.5),{tint:C.gold});r.draw(this.base.orb,transform(75,1.5,-47,2,2,2),{glow:1});}
 for(const a of s.enemies)if(a.telegraph){const g=a.telegraph,radius=g.radius,f=1-g.timer/g.total;r.draw(this.disc,transform(g.x,.035,g.z,radius,1,radius),{tint:[1,.19,.1],alpha:.11+f*.2,glow:.6});r.draw(this.ring,transform(g.x,.05,g.z,radius*f,1,radius*f),{tint:[1,.54,.15],glow:.8});}
 for(const b of s.bolts){r.draw(this.base.orb,transform(b.x,b.y,b.z,1,1,1),{tint:b.team==='human'||b.team==='amber'?[.9,1,1]:[1,.3,.2],glow:1.3});r.draw(this.sword,transform(b.x,b.y,b.z,.35,.35,.45,Math.atan2(b.dx,b.dz)+Math.PI),{glow:1,tint:C.teal});}
 if(s.range)for(const n of s.range.targets)if(!n.hit){r.draw(this.crystal,transform(n.x,.4,n.z,.55,.65,.55),{tint:C.gold,glow:.5});r.draw(this.ring,transform(n.x,.08,n.z,.8,1,.8),{tint:C.gold,glow:.5});}
 for(let i=0;i<(this.reduced?0:24);i++){let x=Math.sin(i*47.1)*39,z=Math.cos(i*31.7)*29+8,y=1.3+Math.sin(at*.5+i)*.5;r.draw(this.base.orb,transform(x,y,z,.16,.16,.16),{glow:1.1,alpha:.65});}
 }
 project(x,y,z){return project([x,y,z],this.r.vp,innerWidth,innerHeight);}
 map(canvas,s){const c=canvas.getContext('2d');c.clearRect(0,0,220,220);c.save();c.translate(110,115);const mode=s.mode==='world',scale=mode?1.5:3.2,a=mode?{x:0,z:0}:ARENAS[s.mode];c.scale(scale,scale);c.translate(-a.x,-a.z);c.fillStyle='#486d6477';if(mode){for(const g of Rain.GROUND){c.beginPath();g.poly.forEach(([x,z],i)=>i?c.lineTo(x,z):c.moveTo(x,z));c.closePath();c.fill();}c.strokeStyle=Rain.bridgeOpen(s.rain)?'#efd795':'#895b42';c.lineWidth=3;c.beginPath();c.moveTo(0,-7);c.lineTo(0,-19);c.stroke();for(const l of LANDMARKS){c.fillStyle=s.discoveries.includes(l.id)?'#e9d095':'#83a19a';c.fillRect(l.x-1,l.z-1,2,2);}}else{c.beginPath();c.arc(a.x,a.z,a.r,0,7);c.fill();}for(const e of s.enemies)if(e.hp>0){c.fillStyle=e.team==='amber'?'#ecc870':'#f17a66';c.beginPath();c.arc(e.x,e.z,1.3,0,7);c.fill();}c.translate(s.hero.x,s.hero.z);c.rotate(-s.hero.angle);c.fillStyle='#faf2d4';c.beginPath();c.moveTo(0,3);c.lineTo(-1.8,-2);c.lineTo(1.8,-2);c.fill();c.restore();}
}
